def is_simple_power(x, n):
    """Your task is to write a function that returns true if a number x is a simple
    power of n and false in other cases.
    x is a simple power of n if n**int=x
    For example:
    is_simple_power(1, 4) => true
    is_simple_power(2, 2) => true
    is_simple_power(8, 2) => true
    is_simple_power(3, 2) => false
    is_simple_power(3, 1) => false
    is_simple_power(5, 3) => false
    """
    if n == 0:
        return x == 1 or x == 0
    if n == 1:
        return x == 1
    if n == -1:
        return x == 1 or x == -1
    if x == 1:
        return True
    if x == 0:
        return False

    import math
    try:
        exponent = math.log(abs(x)) / math.log(abs(n))
    except ValueError:
        return False

    if abs(exponent - round(exponent)) > 1e-10:
        return False

    rounded_exponent = round(exponent)

    if n > 0:
        return n ** rounded_exponent == x
    else:
        if rounded_exponent < 0 or rounded_exponent % 2 == 1:
            return (-abs(n)) ** rounded_exponent == x
        else:
            return (abs(n)) ** rounded_exponent == x

</code>

